function caesar(text, shift) {
  return [...text.toLowerCase()].map(ch => {
    if (ch < "a" || ch > "z") return ch;            // leave non-letters alone
    const code = (ch.charCodeAt(0) - 97 + shift + 26) % 26;
    return String.fromCharCode(code + 97);
  }).join("");
}
caesar("abc", 4);   // "efg"  (encrypt, key = 4)
caesar("efg", -4);  // "abc"  (decrypt with the same key, reversed)
